CREATE TABLE flow_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, camera_x REAL, camera_y REAL, camera_zoom REAL, camera_x_ieee754_bits INTEGER NOT NULL, camera_x_numeric_class TEXT NOT NULL, camera_y_ieee754_bits INTEGER NOT NULL, camera_y_numeric_class TEXT NOT NULL, camera_zoom_ieee754_bits INTEGER NOT NULL, camera_zoom_numeric_class TEXT NOT NULL);
CREATE TABLE flow_widget (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES flow_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE flow_neuron_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), neuron_kind TEXT NOT NULL, params_id INTEGER NOT NULL REFERENCES flow_dictionary(id), preview INTEGER NOT NULL);
CREATE TABLE flow_widget_port (id INTEGER PRIMARY KEY, neuron_widget_id INTEGER NOT NULL REFERENCES flow_neuron_widget(id), side TEXT NOT NULL, ordinal INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE flow_slider_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), label TEXT NOT NULL, value REAL, minimum REAL, maximum REAL, step REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL, minimum_ieee754_bits INTEGER NOT NULL, minimum_numeric_class TEXT NOT NULL, maximum_ieee754_bits INTEGER NOT NULL, maximum_numeric_class TEXT NOT NULL, step_ieee754_bits INTEGER NOT NULL, step_numeric_class TEXT NOT NULL);
CREATE TABLE flow_note_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), text TEXT NOT NULL);
CREATE TABLE flow_image_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), source TEXT NOT NULL);
CREATE TABLE flow_variable_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), name TEXT NOT NULL, schema TEXT NOT NULL);
CREATE TABLE flow_preview_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), preview_id INTEGER NOT NULL REFERENCES flow_dictionary(id));
CREATE TABLE flow_widget_expanded (id INTEGER PRIMARY KEY, preview_widget_id INTEGER NOT NULL REFERENCES flow_preview_widget(id), ordinal INTEGER NOT NULL, path TEXT NOT NULL);
CREATE TABLE flow_action_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), action TEXT NOT NULL);
CREATE TABLE flow_export_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), format TEXT NOT NULL);
CREATE TABLE flow_cluster_widget (id INTEGER PRIMARY KEY, widget_id INTEGER NOT NULL REFERENCES flow_widget(id), name TEXT NOT NULL, tree_id INTEGER NOT NULL REFERENCES flow_tree(id), gui_id INTEGER NOT NULL REFERENCES flow_gui(id));
CREATE TABLE flow_synapse (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES flow_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, from_neuron TEXT NOT NULL, to_neuron TEXT NOT NULL, from_port TEXT NOT NULL, to_port TEXT NOT NULL);
CREATE TABLE flow_layout (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES flow_document(id), ordinal INTEGER NOT NULL, map_key TEXT NOT NULL, x REAL, y REAL, x_ieee754_bits INTEGER NOT NULL, x_numeric_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_numeric_class TEXT NOT NULL);
CREATE TABLE flow_gui (id INTEGER PRIMARY KEY, camera_x REAL, camera_y REAL, camera_zoom REAL, camera_x_ieee754_bits INTEGER NOT NULL, camera_x_numeric_class TEXT NOT NULL, camera_y_ieee754_bits INTEGER NOT NULL, camera_y_numeric_class TEXT NOT NULL, camera_zoom_ieee754_bits INTEGER NOT NULL, camera_zoom_numeric_class TEXT NOT NULL);
CREATE TABLE flow_gui_node (id INTEGER PRIMARY KEY, gui_id INTEGER NOT NULL REFERENCES flow_gui(id), ordinal INTEGER NOT NULL, map_key TEXT NOT NULL, x REAL, y REAL, chrome_kind TEXT NOT NULL, x_ieee754_bits INTEGER NOT NULL, x_numeric_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_numeric_class TEXT NOT NULL);
CREATE TABLE flow_chrome_plain (id INTEGER PRIMARY KEY, gui_node_id INTEGER NOT NULL REFERENCES flow_gui_node(id), preview INTEGER NOT NULL);
CREATE TABLE flow_chrome_slider (id INTEGER PRIMARY KEY, gui_node_id INTEGER NOT NULL REFERENCES flow_gui_node(id), label TEXT NOT NULL, minimum REAL, maximum REAL, step REAL, value REAL, minimum_ieee754_bits INTEGER NOT NULL, minimum_numeric_class TEXT NOT NULL, maximum_ieee754_bits INTEGER NOT NULL, maximum_numeric_class TEXT NOT NULL, step_ieee754_bits INTEGER NOT NULL, step_numeric_class TEXT NOT NULL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE flow_chrome_note (id INTEGER PRIMARY KEY, gui_node_id INTEGER NOT NULL REFERENCES flow_gui_node(id), text TEXT NOT NULL);
CREATE TABLE flow_chrome_image (id INTEGER PRIMARY KEY, gui_node_id INTEGER NOT NULL REFERENCES flow_gui_node(id), source TEXT NOT NULL);
CREATE TABLE flow_chrome_variable (id INTEGER PRIMARY KEY, gui_node_id INTEGER NOT NULL REFERENCES flow_gui_node(id), name TEXT NOT NULL, schema TEXT NOT NULL);
CREATE TABLE flow_gui_preview (id INTEGER PRIMARY KEY, gui_id INTEGER NOT NULL REFERENCES flow_gui(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, mode TEXT NOT NULL, preview_id INTEGER NOT NULL REFERENCES flow_dictionary(id));
CREATE TABLE flow_preview_source (id INTEGER PRIMARY KEY, gui_preview_id INTEGER NOT NULL REFERENCES flow_gui_preview(id), neuron TEXT NOT NULL, channel TEXT NOT NULL);
CREATE TABLE flow_preview_layout (id INTEGER PRIMARY KEY, gui_preview_id INTEGER NOT NULL REFERENCES flow_gui_preview(id), x REAL, y REAL, x_ieee754_bits INTEGER NOT NULL, x_numeric_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_numeric_class TEXT NOT NULL);
CREATE TABLE flow_gui_expanded (id INTEGER PRIMARY KEY, gui_preview_id INTEGER NOT NULL REFERENCES flow_gui_preview(id), ordinal INTEGER NOT NULL, path TEXT NOT NULL);
CREATE TABLE flow_tree (id INTEGER PRIMARY KEY);
CREATE TABLE flow_tree_neuron (id INTEGER PRIMARY KEY, tree_id INTEGER NOT NULL REFERENCES flow_tree(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, kind TEXT NOT NULL, params_id INTEGER NOT NULL REFERENCES flow_dictionary(id), child_tree_id INTEGER REFERENCES flow_tree(id));
CREATE TABLE flow_tree_synapse (id INTEGER PRIMARY KEY, tree_id INTEGER NOT NULL REFERENCES flow_tree(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, from_neuron TEXT NOT NULL, to_neuron TEXT NOT NULL, from_port TEXT NOT NULL, to_port TEXT NOT NULL);
CREATE TABLE flow_dictionary (id INTEGER PRIMARY KEY);
CREATE TABLE flow_dictionary_entry (id INTEGER PRIMARY KEY, dictionary_id INTEGER NOT NULL REFERENCES flow_dictionary(id), ordinal INTEGER NOT NULL, map_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id));
CREATE TABLE flow_neural_value (id INTEGER PRIMARY KEY, variant TEXT NOT NULL);
CREATE TABLE flow_neural_boolean (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id), value INTEGER NOT NULL);
CREATE TABLE flow_neural_integer (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id), value INTEGER NOT NULL);
CREATE TABLE flow_neural_decimal (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE flow_neural_text (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id), value TEXT NOT NULL);
CREATE TABLE flow_neural_dictionary (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES flow_neural_value(id), dictionary_id INTEGER NOT NULL REFERENCES flow_dictionary(id));
